mapper.select:
SELECT COUNT(*) AS itemCount, SUM(total) AS totalCount
FROM (SELECT class_key, SUM(val) AS total
      FROM (SELECT class_key, total_count AS val
            FROM erp_order
            WHERE yy = #{year}
              AND mm = #{month}
              AND center_code = #{centerCode}

            UNION ALL

            SELECT class_key,
                   CASE
                       WHEN reorder_type = 'ADD' THEN count
                       WHEN reorder_type = 'RETURN' THEN -count
                       ELSE 0
                       END
            FROM erp_reorder
            WHERE yy = #{year}
              AND mm = #{month}
              AND center_code = #{centerCode}
              AND confirmed = 'checked') AS inner_sub
      GROUP BY class_key) AS sub

; WITH T AS (SELECT o.created_at, cc.class_key, CONVERT(VARCHAR (10), o.created_at, 120) AS orderDate, cc.class_name AS className, uc.unit_name AS unitName, o.total_count AS totalCount, up.unit_price AS unitPrice, o.total_count * up.unit_price AS totalPrice, u.user_name AS userName FROM erp_order o JOIN erp_class_code cc ON CASE WHEN o.class_key LIKE 'N%' THEN SUBSTRING(o.class_key, 2, LEN(o.class_key)) ELSE o.class_key END = cc.class_key JOIN erp_unit_code uc ON o.unit_key = uc.unit_key JOIN erp_user u ON o.user_code = u.user_code JOIN erp_unit_price up ON o.class_key = up.class_key WHERE o.yy = #{year} AND o.mm = #{month} AND o.center_code = #{centerCode}
UNION ALL
SELECT r.created_at, cc.class_key, CONVERT(VARCHAR (10), r.created_at, 120), cc.class_name, uc.unit_name, CASE WHEN r.reorder_type = 'add' THEN r.count WHEN r.reorder_type = 'return' THEN -r.count ELSE 0 END, up.unit_price, CASE WHEN r.reorder_type = 'add' THEN r.count * up.unit_price WHEN r.reorder_type = 'return' THEN -(r.count * up.unit_price) ELSE 0 END, u.user_name FROM erp_reorder r JOIN erp_class_code cc ON CASE WHEN r.class_key LIKE 'N%' THEN SUBSTRING(r.class_key, 2, LEN(r.class_key)) ELSE r.class_key END = cc.class_key JOIN erp_unit_code uc ON r.unit_key = uc.unit_key JOIN erp_user u ON r.user_code = u.user_code JOIN erp_unit_price up ON r.class_key = up.class_key WHERE r.yy = #{year} AND r.mm = #{month} AND r.center_code = #{centerCode} AND r.confirmed = 'checked')
SELECT orderDate, className, unitName, totalCount, unitPrice, totalPrice, userName FROM (SELECT 0 AS sort_order, created_at, CASE WHEN class_key = 'Y' THEN 1 WHEN class_key = 'S' THEN 2 WHEN class_key = 'P' THEN 3 WHEN class_key = 'ES' THEN 4 WHEN class_key = 'EP' THEN 5 WHEN class_key = 'EG' THEN 6 WHEN class_key = 'ED' THEN 7 WHEN class_key = 'HSN' THEN 8 WHEN class_key = 'HSU' THEN 9 WHEN class_key = 'HSX' THEN 10 WHEN class_key = 'HSS' THEN 11 WHEN class_key = 'HSA' THEN 12 WHEN class_key = 'K' THEN 13 WHEN class_key = 'M' THEN 14 WHEN class_key = 'J' THEN 15 WHEN class_key = 'SU' THEN 16 WHEN class_key = 'DU' THEN 17 WHEN class_key = 'BSN' THEN 18 WHEN class_key = 'BSU' THEN 19 WHEN class_key = 'BSX' THEN 20 WHEN class_key = 'BSS' THEN 21 END AS class_order, orderDate, className, unitName, totalCount, unitPrice, totalPrice, userName FROM T) X ORDER BY sort_order, created_at, class_order;
